import { describe, expect, it } from "vitest";
import {
  InvalidSlugError,
  SLUG_MAX_LENGTH,
  assertValidSlug,
  isReservedSlug,
  isValidSlug,
  projectKeyFromName,
  slugify,
  uniqueSlug,
} from "@/lib/slug";

describe("slugify", () => {
  it("lowercases, strips punctuation and collapses separators", () => {
    expect(slugify("Taskflow Core Team")).toBe("taskflow-core-team");
    expect(slugify("  Hello,   World!  ")).toBe("hello-world");
    expect(slugify("a---b")).toBe("a-b");
  });

  it("strips diacritics rather than dropping the letter", () => {
    expect(slugify("Café Münster")).toBe("cafe-munster");
  });

  it("never emits a leading or trailing hyphen", () => {
    expect(slugify("--edge--")).toBe("edge");
    expect(slugify("!!!")).toBe("");
  });

  it("respects the maximum length", () => {
    expect(slugify("x".repeat(200)).length).toBeLessThanOrEqual(SLUG_MAX_LENGTH);
  });
});

describe("slug validation", () => {
  it("accepts well-formed slugs and rejects malformed ones", () => {
    expect(isValidSlug("acme-corp")).toBe(true);
    expect(isValidSlug("a")).toBe(false);
    expect(isValidSlug("Acme")).toBe(false);
    expect(isValidSlug("acme--corp")).toBe(false);
    expect(isValidSlug("-acme")).toBe(false);
  });

  it("knows the reserved slugs", () => {
    expect(isReservedSlug("settings")).toBe(true);
    expect(isReservedSlug("acme")).toBe(false);
  });

  it("assertValidSlug throws InvalidSlugError for malformed and reserved values", () => {
    expect(() => assertValidSlug("acme-corp")).not.toThrow();
    expect(() => assertValidSlug("Acme")).toThrow(InvalidSlugError);
    expect(() => assertValidSlug("billing")).toThrow(InvalidSlugError);
  });
});

describe("uniqueSlug", () => {
  it("returns the base slug when it is free", () => {
    expect(uniqueSlug("Acme Corp", [])).toBe("acme-corp");
  });

  it("appends an incrementing suffix on collision", () => {
    expect(uniqueSlug("Acme Corp", ["acme-corp"])).toBe("acme-corp-2");
    expect(uniqueSlug("Acme Corp", ["acme-corp", "acme-corp-2"])).toBe("acme-corp-3");
  });

  it("skips reserved slugs", () => {
    expect(uniqueSlug("Billing", [])).toBe("billing-2");
  });

  it("falls back to a usable base when the input slugifies to nothing", () => {
    expect(uniqueSlug("!!!", [])).toBe("item");
  });
});

describe("projectKeyFromName", () => {
  it("uses initials for multi-word names", () => {
    expect(projectKeyFromName("Mobile App Redesign")).toBe("MAR");
  });

  it("uses a prefix for single-word names", () => {
    expect(projectKeyFromName("Platform")).toBe("PLA");
  });

  it("always returns a non-empty uppercase key", () => {
    expect(projectKeyFromName("###")).toBe("TASK");
  });
});
/** Route shapes and query-string composition. */
import { describe, expect, it } from "vitest";
import {
  issuePath,
  orgPath,
  projectPath,
  settingsPath,
  withSearchParams,
} from "@/lib/url";

describe("lib/url", () => {
  it("builds an org-rooted path", () => {
    expect(orgPath("acme")).toBe("/acme");
    expect(orgPath("acme", "issues")).toBe("/acme/issues");
    expect(orgPath("acme", "issues", "new")).toBe("/acme/issues/new");
  });

  it("encodes segments so a slug cannot break out of the path", () => {
    expect(orgPath("acme corp")).toBe("/acme%20corp");
    expect(orgPath("acme", "a/b")).toBe("/acme/a%2Fb");
  });

  it("nests project paths under the org", () => {
    expect(projectPath("acme", "website")).toBe("/acme/projects/website");
    expect(projectPath("acme", "website", "board")).toBe(
      "/acme/projects/website/board",
    );
  });

  it("builds an issue path from the issue number", () => {
    expect(issuePath("acme", "website", 142)).toBe(
      "/acme/projects/website/issues/142",
    );
  });

  it("builds settings paths with and without a section", () => {
    expect(settingsPath("acme")).toBe("/acme/settings");
    expect(settingsPath("acme", "billing")).toBe("/acme/settings/billing");
  });

  it("appends query parameters and stringifies numbers", () => {
    expect(withSearchParams("/acme/issues", { status: "todo", page: 2 })).toBe(
      "/acme/issues?status=todo&page=2",
    );
  });

  it("drops undefined parameters instead of writing 'undefined'", () => {
    expect(withSearchParams("/acme/issues", { status: undefined })).toBe(
      "/acme/issues",
    );
  });

  it("merges into an existing query string, overwriting on conflict", () => {
    expect(withSearchParams("/acme/issues?status=done&page=1", { page: 3 })).toBe(
      "/acme/issues?status=done&page=3",
    );
  });

  it("removes a parameter when its value is undefined", () => {
    expect(withSearchParams("/acme/issues?status=done", { status: undefined })).toBe(
      "/acme/issues",
    );
  });
});
/**
 * Fixtures for the server suite: a throwaway SQLite file plus a helper that
 * builds one fully-populated tenant (org, four members, a project) through the
 * real repositories, so the rows under test are the rows production writes.
 *
 * Kept apart from `tests/helpers/*` — those belong to another owner.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import type { PlanId } from "@/types/billing";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export interface Tenant {
  readonly org: Organization;
  readonly project: Project;
  readonly actors: Readonly<Record<Role, Actor>>;
  readonly userIds: Readonly<Record<Role, UserId>>;
}

const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

/**
 * Points the connection at a fresh database file and migrates it. Call from
 * `beforeAll`; the returned function removes the directory again.
 *
 * A file rather than `:memory:` because `runMigrations` and the app client
 * open separate connections, and only a file is shared between the two.
 */
export async function useTemporaryDatabase(): Promise<() => void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
  const path = join(dir, "taskflow.db");

  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  return () => {
    rmSync(dir, { recursive: true, force: true });
  };
}

/**
 * Creates one organization with a member in every role and a single project.
 * `plan` decides which quotas apply — the free plan's three seats is what the
 * invite-limit test leans on.
 */
export async function createTenant(
  slug: string,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });

  const org = await orgRepo.insertOrg(
    { name: `${slug} inc`, slug, plan },
    owner.id,
  );

  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");

  const userIds: Partial<Record<Role, UserId>> = {};
  const actors: Partial<Record<Role, Actor>> = {};

  for (const role of ROLES) {
    const user =
      role === "owner"
        ? owner
        : await userRepo.insertUser({
            email: `${role}@${slug}.test`,
            name: `${slug} ${role}`,
            passwordHash: "seed",
          });

    await memberRepo.insertMember(org.id, user.id, role, null);

    userIds[role] = user.id;
    actors[role] = { userId: user.id, orgId: org.id, role };
  }

  const project = await projectRepo.insertProject({
    orgId: org.id,
    name: `${slug} platform`,
    slug: "platform",
    key: "PLAT",
    description: null,
    visibility: "org",
    leadId: owner.id,
    color: "#6366f1",
    targetDate: null,
  });

  return {
    org,
    project,
    actors: actors as Readonly<Record<Role, Actor>>,
    userIds: userIds as Readonly<Record<Role, UserId>>,
  };
}

/** Minimal `CreateIssueInput` with the schema's defaults already applied. */
export function issueInput(
  orgId: OrgId,
  projectId: Project["id"],
  overrides: Partial<{
    title: string;
    assigneeId: UserId | null;
    dueAt: string | null;
  }> = {},
) {
  return {
    orgId,
    projectId,
    title: overrides.title ?? "Ship the thing",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeId: (overrides.assigneeId ?? null) as UserId | null,
    parentId: null,
    estimate: null,
    dueAt: (overrides.dueAt ?? null) as never,
    labelIds: [],
  };
}
