import { resolveActorForOrg } from \"@/server/services/session-service\";
import { toIsoTimestamp } from \"@/types/common\";
import { createTenant, useTemporaryDatabase } from \"../server/_support/fixtures\";
import type { Unsubscribe } from \"@/types/event\";

let cleanup: () => void;
const offs: Unsubscribe[] = [];
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterEach(() => { vi.restoreAllMocks(); while (offs.length) offs.pop()?.(); });
afterAll(() => cleanup());

describe(\"workspace slug renames\", () => {
  it(\"updates reads, preserves settings and announces exactly once, with silent no-ops\", async () => {
    const tenant = await createTenant(\"rename-reads\");
    const seen = vi.fn();
    offs.push(subscribe(\"organization.slug_changed\", seen), registerActivityListeners());
    const input = { orgId: tenant.org.id, slug: \"renamed-reads\" };
    const updated = await orgService.renameOrganizationSlug(tenant.actors.admin, input);
    expect(updated).toEqual({ ...tenant.org, slug: input.slug, updatedAt: updated.updatedAt });
    expect(await orgRepo.findOrgById(input.orgId)).toEqual(updated);
    expect((await orgService.getOrganizationSummary(tenant.actors.admin, input.orgId)).organization).toEqual(updated);
    expect(await orgService.listOrganizationsForUser(tenant.userIds.admin)).toContainEqual(updated);
    const principal = { userId: tenant.userIds.admin, email: \"admin@example.test\", activeOrgId: input.orgId, expiresAt: toIsoTimestamp(new Date(Date.now() + 86400000)) };
    for (const slug of [tenant.org.slug, input.slug]) {
      expect(await orgService.resolveOrgBySlug(slug)).toEqual(updated);
      expect(await resolveActorForOrg(principal, slug)).toEqual(tenant.actors.admin);
    }
    expect(seen).toHaveBeenCalledTimes(1);
    expect(seen.mock.calls[0][0]).toMatchObject({ orgId: input.orgId, actorId: tenant.userIds.admin, from: tenant.org.slug, to: input.slug });
    expect(await orgService.renameOrganizationSlug(tenant.actors.admin, input)).toEqual(updated);
    expect(seen).toHaveBeenCalledTimes(1);
    const filter = activityFilterSchema.parse({ orgId: input.orgId, action: [\"organization.slug_changed\"] });
    const audit = await listActivity(tenant.actors.admin, filter);
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({ actorId: tenant.userIds.admin, subjectKind: \"organization\", subjectId: input.orgId, metadata: { from: tenant.org.slug, to: input.slug } });
  });

  it(\"refuses invalid, occupied and archived slugs and unauthorized changes without mutating\", async () => {
    const tenant = await createTenant(\"rename-guards\");
    const other = await createTenant(\"rename-occupied\");
    await orgRepo.archiveOrg(other.org.id);
    const seen = vi.fn();
    offs.push(subscribe(\"organization.slug_changed\", seen));
    for (const slug of [\"Bad slug\", \"settings\", other.org.slug]) {
      await expect(orgService.renameOrganizationSlug(tenant.actors.admin, { orgId: tenant.org.id, slug })).rejects.toBeInstanceOf(InvalidSlugError);
    }
    await expect(orgService.renameOrganizationSlug(tenant.actors.member, { orgId: tenant.org.id, slug: \"rename-denied\" })).rejects.toThrow();
    await expect(orgService.renameOrganizationSlug(other.actors.owner, { orgId: tenant.org.id, slug: \"rename-denied\" })).rejects.toThrow();
    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(tenant.org);
    expect(seen).not.toHaveBeenCalled();
  });

  it(\"keeps independent holds, allows renaming back, and releases at the exact boundary\", async () => {
    const tenant = await createTenant(\"rename-chain\");
    const other = await createTenant(\"rename-contender\");
    const start = Date.now();
    const day = 86400000;
    vi.spyOn(Date, \"now\").mockReturnValue(start);
    await orgService.renameOrganizationSlug(tenant.actors.admin, { orgId: tenant.org.id, slug: \"rename-middle\" });
    await expect(orgService.renameOrganizationSlug(other.actors.admin, { orgId: other.org.id, slug: tenant.org.slug })).rejects.toBeInstanceOf(InvalidSlugError);
    const derived = await orgService.createOrganization(other.userIds.owner, { name: \"Derived\", slug: tenant.org.slug, plan: \"free\" });
    expect(derived.slug).toBe("'`${tenant.org.slug}-2`);
    vi.mocked(Date.now).mockReturnValue(start + day);
    await orgService.renameOrganizationSlug(tenant.actors.admin, { orgId: tenant.org.id, slug: "rename-last" });
    vi.mocked(Date.now).mockReturnValue(start + ORG_SLUG_HOLD_DAYS * day - 1);
    expect((await orgRepo.findOrgBySlug(tenant.org.slug))?.id).toBe(tenant.org.id);
    vi.mocked(Date.now).mockReturnValue(start + ORG_SLUG_HOLD_DAYS * day);
    expect(await orgRepo.findOrgBySlug(tenant.org.slug)).toBeNull();
    expect((await orgRepo.findOrgBySlug("rename-middle"))?.id).toBe(tenant.org.id);
    const reclaimed = await orgService.createOrganization(other.userIds.owner, { name: "Reclaimed", slug: tenant.org.slug, plan: "free" });
    expect(reclaimed.slug).toBe(tenant.org.slug);
    await orgService.renameOrganizationSlug(tenant.actors.admin, { orgId: tenant.org.id, slug: "rename-middle" });
    vi.mocked(Date.now).mockReturnValue(start + (ORG_SLUG_HOLD_DAYS + 1) * day);
    expect((await orgRepo.findOrgBySlug("rename-middle"))?.slug).toBe("rename-middle");
    expect((await orgRepo.findOrgBySlug("rename-last"))?.slug).toBe("rename-middle");
  });
});
